<template>
  <div class="logs-view bg-light min-vh-100">
    <CompanyNavBar v-if="user.userRole === 0" />
    <NavBarVue v-else />

    <b-container fluid class="py-4">
      <b-row class="justify-content-center">
        <b-col lg="11">
          <b-card no-body class="border-0 shadow-sm mb-4">
            <b-card-body class="p-4">
              <b-row align-v="center">
                <b-col lg="4" md="12" class="mb-3 mb-lg-0">
                  <h4 class="text-dark font-weight-bold mb-1">
                    <b-icon
                      icon="clock-history"
                      class="text-mbr-green mr-2"
                    ></b-icon>
                    Histórico de Operações
                  </h4>
                  <p class="text-muted small mb-0">
                    Auditoria detalhada de atividades do sistema
                  </p>
                </b-col>

                <b-col lg="8" md="12">
                  <b-row class="align-items-end justify-content-end">
                    <b-col sm="4" class="mb-2 mb-sm-0">
                      <label class="small font-weight-bold text-muted"
                        >Desde:</label
                      >
                      <b-form-datepicker
                        v-model="fromDate"
                        size="sm"
                        placeholder="Data inicial"
                        local="pt-BR"
                        class="border-0 bg-light"
                      ></b-form-datepicker>
                    </b-col>
                    <b-col sm="4" class="mb-2 mb-sm-0">
                      <label class="small font-weight-bold text-muted"
                        >Até:</label
                      >
                      <b-form-datepicker
                        v-model="toDate"
                        size="sm"
                        placeholder="Data final"
                        local="pt-BR"
                        class="border-0 bg-light"
                      ></b-form-datepicker>
                    </b-col>
                    <b-col sm="auto">
                      <b-button
                        variant="mbr-green"
                        size="sm"
                        @click="getSystemLogs()"
                        :disabled="isLoading"
                        class="px-4 shadow-sm"
                      >
                        <b-icon icon="search" v-if="!isLoading"></b-icon>
                        <b-spinner small v-else></b-spinner>
                        Filtrar
                      </b-button>
                    </b-col>
                  </b-row>
                </b-col>
              </b-row>
            </b-card-body>
          </b-card>

          <b-card no-body class="border-0 shadow-sm">
            <b-card-header class="bg-white border-bottom-0 pt-3">
              <div class="d-flex justify-content-between align-items-center">
                <span class="text-muted small"
                  >Mostrando <b>{{ logs.length }}</b> registros</span
                >
                <b-button-group size="sm">
                  <b-button
                    variant="outline-danger"
                    @click="downloadSystemLogsPDF()"
                    title="PDF"
                  >
                    <b-icon icon="file-earmark-pdf"></b-icon> PDF
                  </b-button>
                  <b-button
                    variant="outline-success"
                    @click="downloadSystemLogsExcel()"
                    title="Excel"
                  >
                    <b-icon icon="file-earmark-excel"></b-icon> Excel
                  </b-button>
                </b-button-group>
              </div>
            </b-card-header>

            <b-overlay :show="isLoading" rounded="sm" opacity="0.6">
              <div class="table-responsive">
                <table class="table table-hover border-0 mb-0">
                  <thead
                    class="bg-light-mbr text-mbr-green small font-weight-bold text-uppercase"
                  >
                    <tr>
                      <th class="border-0 pl-4">Horário / Data</th>
                      <th class="border-0">Usuário</th>
                      <th class="border-0">Acção</th>
                      <th class="border-0">Descrição</th>
                      <th class="border-0 text-center">Módulo</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="log in logs" :key="log.id" class="log-row">
                      <td class="pl-4 align-middle">
                        <div class="d-flex flex-column">
                          <span
                            class="font-weight-bold text-dark"
                            style="font-family: 'Courier New', monospace"
                          >
                            {{ formatOnlyTime(log.createdAt) }}
                          </span>
                          <small class="text-muted">{{
                            formatOnlyDate(log.createdAt)
                          }}</small>
                        </div>
                      </td>
                      <td class="align-middle">
                        <div class="d-flex align-items-center">
                          <b-avatar
                            size="1.5rem"
                            variant="light"
                            class="mr-2 text-mbr-green"
                          ></b-avatar>
                          <span class="text-dark font-weight-500">{{
                            log.userName
                          }}</span>
                        </div>
                      </td>
                      <td class="align-middle">
                        <span class="badge badge-soft-mbr px-2 py-1">{{
                          log.action
                        }}</span>
                      </td>
                      <td
                        class="align-middle small text-secondary"
                        style="max-width: 300px"
                      >
                        {{ log.description }}
                      </td>
                      <td class="align-middle text-center">
                        <b-badge pill variant="light" class="text-muted border">
                          {{ log.target || "Sistema" }}
                        </b-badge>
                      </td>
                    </tr>
                    <tr v-if="logs.length === 0">
                      <td colspan="5" class="text-center py-5 text-muted">
                        <b-icon
                          icon="search"
                          font-scale="2"
                          class="mb-2"
                        ></b-icon>
                        <p>Nenhum registro encontrado para este período.</p>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </b-overlay>
          </b-card>
        </b-col>
      </b-row>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import DateFormat from "../utils/dateFormat";
import NavBarVue from "@/components/NavBar";
import CompanyNavBar from "@/components/CompanyNavBar";
import exportFromJSON from "export-from-json";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  name: "LogsView",
  components: { NavBarVue, CompanyNavBar },
  data: () => ({
    fromDate: "",
    toDate: "",
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "logs", "company"]),
  },

  methods: {
    getSystemLogs() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(
          `/api/logs/${this.user.companyId}?from=${this.fromDate}&to=${this.toDate}`
        )
        .then((res) => {
          this.$store.commit("SET_LOGS", res.data.logs);
        })
        .finally(() => {
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    formatOnlyTime(date) {
      return new Date(date).toLocaleTimeString("pt-PT", {
        hour: "2-digit",
        minute: "2-digit",
      });
    },

    formatOnlyDate(date) {
      return DateFormat.formatDate(date);
    },

    // PDF e Excel mantidos com as melhorias de cores da marca
    downloadSystemLogsPDF() {
      const body = [];
      const tableHeader = [
        { text: "Data", style: "columnsTitle" },
        { text: "Técnico", style: "columnsTitle" },
        { text: "Acção", style: "columnsTitle" },
        { text: "Descrição", style: "columnsTitle" },
      ];

      for (let log of this.logs) {
        body.push([
          { text: DateFormat.formatDate(log.createdAt), fontSize: 8 },
          { text: log.userName, fontSize: 8 },
          { text: log.action, fontSize: 8 },
          { text: log.description, fontSize: 8 },
        ]);
      }

      let docDefinition = {
        content: [
          { text: "RELATÓRIO DE AUDITORIA", style: "header" },
          {
            text: `Empresa: ${this.company.companyName}`,
            margin: [0, 5, 0, 15],
            fontSize: 10,
          },
          {
            table: {
              headerRows: 1,
              widths: ["auto", "auto", "auto", "*"],
              body: [tableHeader, ...body],
            },
            layout: "lightHorizontalLines",
          },
        ],
        styles: {
          header: {
            fontSize: 16,
            bold: true,
            color: "#009640",
            margin: [0, 0, 0, 10],
          },
          columnsTitle: {
            fontSize: 9,
            bold: true,
            color: "#ffffff",
            fillColor: "#009640",
          },
        },
      };
      pdfMake.createPdf(docDefinition).open();
    },

    downloadSystemLogsExcel() {
      const data = this.logs.map((log) => ({
        Data: DateFormat.formatDate(log.createdAt),
        Técnico: log.userName,
        Acção: log.action,
        Descrição: log.description,
      }));
      exportFromJSON({ data, fileName: "Logs_Sistema", exportType: "xls" });
    },
  },
};
</script>

<style scoped>
.text-mbr-green {
  color: #009640 !important;
}
.bg-mbr-green {
  background-color: #009640 !important;
}
.btn-mbr-green {
  background-color: #009640;
  color: white;
  border: none;
}
.btn-mbr-green:hover {
  background-color: #007a33;
}

.bg-light-mbr {
  background-color: #f8fdf9;
}

.log-row:hover {
  background-color: rgba(0, 150, 64, 0.02) !important;
}

.badge-soft-mbr {
  background-color: rgba(0, 150, 64, 0.1);
  color: #009640;
  font-weight: 600;
  border-radius: 4px;
}

.font-weight-500 {
  font-weight: 500;
}

/* Estilo para remover bordas padrão do datepicker para parecer mais moderno */
::v-deep .b-form-datepicker .btn {
  padding: 0.2rem 0.5rem;
}
</style>
